
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_mpw3lyp_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_mpw3lyp", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.441550532985695e+00, -3.377244579785446e+00, -3.287182895165189e+00, -3.162521162126315e+00, -2.992851118339735e+00, -2.767432759104500e+00, -2.478076136948625e+00, -2.124209966178047e+00, -1.719164599786015e+00, -1.291428209783167e+00, -8.710986537753254e-01, -5.907183699345400e-01, -5.097871767252145e-01, -4.254459444098188e-01, -3.102776674181548e-01, -1.948771685677189e-01, -1.076770165105210e-01, -3.997175963162027e-02, -2.330888724793986e-03, -2.362082846938792e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


